entries.syntax:
// Encapsulation of FLAC in ISO Base Media File Format (Xiph, isoflac.txt), 3.3.1 FLAC Sample Entry
class FLACSampleEntry() extends AudioSampleEntry ('fLaC'){
	FLACSpecificBox();
}

// 3.3.2 FLAC Specific Box: the metadata blocks of the stream, to the end of the box
aligned(8) class FLACSpecificBox extends FullBox('dfLa', version = 0, 0){
	FLACMetadataBlock blocks[];
}
aligned(8) class FLACMetadataBlock {
	unsigned int(1) LastMetadataBlockFlag;
	unsigned int(7) BlockType;
	unsigned int(24) Length;
	unsigned int(8) BlockData[Length];
}
